import {ingredients,name} from './ingredients.js';
import {art} from './art.js';
import {initial,reducer,fees,money,price} from './state.js';
import whopperPhoto from '../Assets/catalog/whopper.png';
import whopperDuploPhoto from '../Assets/catalog/whopper-duplo.png';
import baconPhoto from '../Assets/catalog/bacon.png';
import cheeseburgerPhoto from '../Assets/catalog/cheeseburger.png';
// Prototype question: can layered ingredients support opening, removal, restoration and order customization?
let state=initial;
const $=id=>document.getElementById(id);function dispatch(a){state=reducer(state,a);render()}
function buildBurger(el,interactive=false){el.innerHTML=ingredients.map((i,index)=>`<button class="layer" data-id="${i.id}" style="--y:${interactive?(78-index*(70/(ingredients.length-1)))+'%':i.y+'px'};--z:${i.z}" ${interactive&&!i.locked?'':'disabled'} aria-label="Retirar ${i.name}">${art(i.id)}</button>`).join('');if(interactive)el.querySelectorAll('.layer:not(:disabled)').forEach(bindLayer)}
buildBurger($('hero-burger'));buildBurger($('pg-burger'),true);
const products=['Whopper Clássico','Whopper Duplo','Bacon Supreme','Cheese Burger'];const catalogPhotos=[whopperPhoto,whopperDuploPhoto,baconPhoto,cheeseburgerPhoto];$('grid').innerHTML=products.map((p,i)=>`<button class="card" aria-pressed="${i===0}" data-product="${i}">${i===0?'<span class="badge">★ Selecionado</span>':''}<img class="catalog-photo" src="${catalogPhotos[i]}" width="400" height="300" alt="" loading="lazy" decoding="async">${p}${i?'<small>Em breve neste protótipo</small>':''}</button>`).join('');$('grid').querySelectorAll('button.card').forEach(b=>b.onclick=()=>b.dataset.product==='0'?$('edit').focus():toast('Vamos validar o Whopper primeiro. Os demais vêm depois.'));
function closedPositions(removed){let y=242;const thickness={meat:36,cheese:9,pickles:8,onion:8,tomato:12,ketchup:4,lettuce:15,mayo:4,top:62};const positions={bottom:y};for(const ingredient of ingredients.slice(1)){if(removed.includes(ingredient.id))continue;y-=thickness[ingredient.id];positions[ingredient.id]=y}return positions}
function render(){const positions=closedPositions(state.removed);document.querySelectorAll('#hero-burger .layer').forEach(b=>{if(positions[b.dataset.id]!==undefined)b.style.top=positions[b.dataset.id]+'px'});document.querySelectorAll('#hero-burger .layer').forEach(b=>b.classList.toggle('removed',state.removed.includes(b.dataset.id)));$('combo').checked=state.combo;document.querySelectorAll('.size').forEach(b=>{b.disabled=!state.combo;b.setAttribute('aria-pressed',String(b.dataset.size===state.size))});$('fee').innerHTML=state.combo?`Combo ${state.size}:<br>+ ${money(fees[state.size])}`:'Só o sanduíche';$('total').textContent=money(price(state));$('custom-note').textContent=state.removed.length?'Sem '+state.removed.map(name).join(', ').toLowerCase():'Preparado com todos os ingredientes';$('playground').classList.toggle('open',state.editing);document.querySelectorAll('#pg-burger .layer').forEach(b=>{b.classList.toggle('removed',state.draft.includes(b.dataset.id));b.tabIndex=state.draft.includes(b.dataset.id)?-1:0;b.setAttribute('aria-hidden',String(state.draft.includes(b.dataset.id)));b.setAttribute('aria-label','Retirar '+name(b.dataset.id))});$('tray-message').textContent=state.draft.length?'Use + nos chips para devolver os ingredientes.':'Arraste os ingredientes para cá ou use os chips abaixo.';$('controls').innerHTML=ingredients.filter(i=>!i.locked).map(i=>`<button class="ingredient-chip" data-toggle="${i.id}" aria-label="${state.draft.includes(i.id)?'Recolocar':'Retirar'} ${i.name}" aria-pressed="${!state.draft.includes(i.id)}"><span class="chip-icon" aria-hidden="true">${state.draft.includes(i.id)?'＋':'✓'}</span> ${i.name}</button>`).join('');$('controls').querySelectorAll('button').forEach(b=>b.onclick=()=>{const id=b.dataset.toggle;dispatch({type:'toggle',id});$('controls').querySelector(`[data-toggle="${id}"]`).focus()});$('state').textContent=`Whopper Clássico · ${state.draft.length?'Sem '+state.draft.map(name).join(', ').toLowerCase():'Todos os ingredientes'} · Remover ingredientes mantém o preço neste protótipo.`;$('cart-count').textContent=state.cart.length;$('cart-items').innerHTML=state.cart.length?state.cart.map((item,i)=>`<div class="cart-row"><b>Whopper Clássico · ${money(item.price)}</b><small>${item.combo?'Combo '+item.size:'Só sanduíche'} · ${item.removed.length?'Sem '+item.removed.map(name).join(', ').toLowerCase():'Todos os ingredientes'}</small><button data-delete="${i}">Remover item</button></div>`).join(''):'Seu carrinho está vazio.';$('cart-items').querySelectorAll('button').forEach(b=>b.onclick=()=>dispatch({type:'delete',index:Number(b.dataset.delete)}));$('cart-total').textContent='Total: '+money(state.cart.reduce((n,i)=>n+i.price,0))}
let activeDrag=null;function bindLayer(b){b.addEventListener('pointerdown',e=>{if(e.button!==0)return;activeDrag={b,x:e.clientX,y:e.clientY,moved:false};b.setPointerCapture(e.pointerId);b.classList.add('dragging')});b.addEventListener('pointermove',e=>{if(!activeDrag||activeDrag.b!==b)return;const dx=e.clientX-activeDrag.x,dy=e.clientY-activeDrag.y;if(Math.hypot(dx,dy)>8)activeDrag.moved=true;b.style.transform=`translate3d(${dx}px,${dy}px,80px) rotate(${dx/25}deg)`;const r=$('tray').getBoundingClientRect();$('tray').classList.toggle('over',e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom)});b.addEventListener('pointerup',e=>{if(!activeDrag)return;const drag=activeDrag;activeDrag=null;b.classList.remove('dragging');b.style.transform='';const r=$('tray').getBoundingClientRect(),drop=e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom;$('tray').classList.remove('over');if(drop)dispatch({type:'remove',id:b.dataset.id});else if(!drag.moved)dispatch({type:'toggle',id:b.dataset.id})});b.addEventListener('pointercancel',()=>{activeDrag=null;b.classList.remove('dragging');b.style.transform='';$('tray').classList.remove('over')});b.addEventListener('click',e=>{if(e.detail===0)dispatch({type:'toggle',id:b.dataset.id})})}
let restoreFocus=null,closing=false;function openEditor(){restoreFocus=document.activeElement;dispatch({type:'open'});document.querySelectorAll('#pg-burger .layer').forEach((b,i)=>b.style.top=ingredients[i].y+'px');requestAnimationFrame(()=>requestAnimationFrame(()=>document.querySelectorAll('#pg-burger .layer').forEach(b=>b.style.top='')));document.body.style.overflow='hidden';document.querySelector('header').inert=true;document.querySelector('main').inert=true;$('close').focus()}function closeEditor(type){if(closing)return;const finish=()=>{dispatch({type});closing=false;$('playground').classList.remove('closing');$('playground').querySelectorAll('button').forEach(b=>{b.disabled=Boolean(b.classList.contains('layer')&&ingredients.find(i=>i.id===b.dataset.id)?.locked)});document.body.style.overflow='';document.querySelector('header').inert=false;document.querySelector('main').inert=false;restoreFocus?.focus()};if(type!=='apply'||matchMedia('(prefers-reduced-motion:reduce)').matches){finish();return}closing=true;$('playground').classList.add('closing');$('playground').querySelectorAll('button').forEach(b=>b.disabled=true);const positions=closedPositions(state.draft),offset=$('pg-stage').clientHeight*.65-242;document.querySelectorAll('#pg-burger .layer').forEach(b=>{if(positions[b.dataset.id]!==undefined)b.style.top=(positions[b.dataset.id]+offset)+'px'});$('state').textContent='Fechando seu hambúrguer…';setTimeout(finish,700)}
$('edit').onclick=openEditor;$('close').onclick=$('cancel').onclick=()=>closeEditor('cancel');$('apply').onclick=()=>closeEditor('apply');$('reset').onclick=()=>dispatch({type:'reset'});$('combo').onchange=e=>dispatch({type:'combo',value:e.target.checked});document.querySelectorAll('.size').forEach(b=>b.onclick=()=>dispatch({type:'size',value:b.dataset.size}));$('add').onclick=()=>{dispatch({type:'add'});toast('Whopper adicionado ao carrinho')};$('cart-open').onclick=()=>{restoreFocus=document.activeElement;$('cart').classList.add('open');document.body.style.overflow='hidden';$('cart-close').focus()};function closeCart(){$('cart').classList.remove('open');document.body.style.overflow='';restoreFocus?.focus()}$('cart-close').onclick=closeCart;$('cart').onclick=e=>{if(e.target===$('cart'))closeCart()};document.querySelectorAll('[data-accessory]').forEach(a=>a.onclick=e=>{e.preventDefault();toast('Categoria prevista para uma próxima etapa')});
document.addEventListener('keydown',e=>{const dialog=state.editing?$('playground'):$('cart').classList.contains('open')?$('cart'):null;if(!dialog)return;if(e.key==='Escape'){state.editing?closeEditor('cancel'):closeCart()}if(e.key==='Tab'){const focusable=[...dialog.querySelectorAll('button:not(:disabled),input')].filter(b=>!b.classList.contains('removed'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});let timer;function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('toast').style.display='none',2800)}$('hero-stage').onpointermove=e=>{if(e.pointerType==='touch'||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const r=$('hero-stage').getBoundingClientRect();$('hero-burger').style.setProperty('--tilt',((e.clientX-r.left)/r.width-.5)*12+'deg')};$('hero-stage').onpointerleave=()=>$('hero-burger').style.setProperty('--tilt','0deg');render();
